export const t = (locale: Locale, key: string) => labels[locale][key] ?? extraLabels[locale][key] ?? pageLabels[locale][key] ?? featureLabels[locale][key] ?? adminLabels[locale][key] ?? notificationLabels[locale][key] ?? supportLabels[locale][key] ?? detailLabels[locale][key] ?? moderationLabels[locale][key] ?? workflowLabels[locale][key] ?? dataLabels[locale][key] ?? sampleContentLabels[locale][key] ?? nutritionLabels[locale][key] ?? adminConsoleLabels[locale][key] ?? backendLabels[locale][key] ?? backendStatusLabels[locale][key] ?? key;
const translationDictionaries: Record<Locale, Record<string, string>>[] = [labels, extraLabels, pageLabels, featureLabels, adminLabels, notificationLabels, supportLabels, detailLabels, moderationLabels, workflowLabels, dataLabels, sampleContentLabels, nutritionLabels, adminConsoleLabels, backendLabels, backendStatusLabels];
export function localizeStoredText(locale: Locale, text: string): string {
  if (!text) return text;
  for (const dictionary of translationDictionaries) {
    for (const sourceLocale of ["kk", "ru", "en"] as const) {
      for (const [key, value] of Object.entries(dictionary[sourceLocale])) {
        if (value === text) return t(locale, key);
      }
    }
  }
  for (const key of ["Planned activity reminder", "Planned meal reminder"]) {
    for (const dictionary of translationDictionaries) {
      for (const sourceLocale of ["kk", "ru", "en"] as const) {
        const template = dictionary[sourceLocale][key];
        if (!template?.includes("{")) continue;
        const parts = [...template.matchAll(/\{(\w+)\}/g)];
        let pattern = "^";
        let cursor = 0;
        for (const part of parts) {
          const before = template.slice(cursor, part.index);
          pattern += before.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "(.+?)";
          cursor = (part.index ?? 0) + part[0].length;
        }
        pattern += template.slice(cursor).replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "$";
        const captures = new RegExp(pattern).exec(text);
        if (!captures) continue;
        let translated = t(locale, key);
        parts.forEach((part, index) => {
          const value = captures[index + 1];
          translated = translated.replace(part[0], part[1] === "date" ? value : localizeStoredText(locale, value));
        });
        return translated;
      }
    }
  }
  const separator = text.indexOf(" · ");
  if (separator > 0) return `${text.slice(0, separator)} · ${localizeStoredText(locale, text.slice(separator + 3))}`;
  return text;
}
export const formatDate = (date: Date, locale: Locale) => {
  if (locale === "kk") {
    const weekdays = ["жексенбі", "дүйсенбі", "сейсенбі", "сәрсенбі", "бейсенбі", "жұма", "сенбі"];
    const months = ["қаңтар", "ақпан", "наурыз", "сәуір", "мамыр", "маусым", "шілде", "тамыз", "қыркүйек", "қазан", "қараша", "желтоқсан"];
    return `${weekdays[date.getDay()]}, ${date.getDate()} ${months[date.getMonth()]}`;
  }
  return date.toLocaleDateString(locale === "ru" ? "ru-RU" : "en-US", { weekday: "long", day: "numeric", month: "long" });
};
export const formatWeekday = (date: Date, locale: Locale) => {
  if (locale === "kk") return ["Жс", "Дс", "Сс", "Ср", "Бс", "Жм", "Сб"][date.getDay()];
  return date.toLocaleDateString(locale === "ru" ? "ru-RU" : "en-US", { weekday: "short" });
};
export const localDayKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
